var minSumSquareDiff = function (nums1, nums2, k1, k2) {
    const n = nums1.length;
    let max = 0;
    let total = 0;
    let k = k1 + k2;

    for (let i = 0; i < n; i++) {
        const diff = Math.abs(nums1[i] - nums2[i]);
        max = Math.max(max, diff);
        total += diff;
    }

    if (k >= total) return 0;

    const freq = new Int32Array(max + 1);

    for (let i = 0; i < n; i++) {
        freq[Math.abs(nums1[i] - nums2[i])]++;
    }

    for (let d = max; d > 0 && k > 0; d--) {
        const reductions = Math.min(k, freq[d]);

        freq[d] -= reductions;
        freq[d - 1] += reductions;
        k -= reductions;
    }

    let result = 0;

    for (let d = 1; d <= max; d++) {
        result += d * d * freq[d];
    }

    return result;
};
